import copy
from collections.abc import Sequence


def capture_runs(frames, selected):
    if isinstance(frames, (str, bytes)) or not isinstance(frames, Sequence):
        raise ValueError("frames must be a sequence")
    if isinstance(selected, (str, bytes)) or not isinstance(selected, Sequence):
        raise ValueError("selected must be a sequence")
    if len(frames) != len(selected) or any(type(flag) is not bool for flag in selected):
        raise ValueError("invalid selection")
    runs = []
    current = []
    for frame, flag in zip(frames, selected):
        if flag:
            current.append(copy.deepcopy(frame))
        elif current:
            runs.append(tuple(current))
            current = []
    return tuple(runs)
```

